INSERT INTO public.scraper_sources (id, source_name, society, base_url, default_event_type, pagination_type, pagination_template, max_pages_hint, detail_is_multipage, active, extraction_instructions) VALUES
  (155, 'British Cardiovascular Society (BCS)', 'BCS', 'https://britishcardiovascularsociety.org.uk/courses/', 'mixed', 'single_page', NULL, 1, FALSE, TRUE, 'Listing: /courses/ Elementor loop, one card per dated course (h6 link to the course''s own EventsAir microsite, ISO date, optional venue/city lines). Plus the next Annual Conference from /annual-conference/ whose dates come from the organiser''s linked rate-card PDF. Detail: server-rendered EventsAir page with date line, venue/location line and a Pricing / Attendance fee block of ''label £amount'' lines (regular/early bird on one line). Courses are course, webinars workshop; conference row has no tiers (delegate fees unpublished).'),
  (156, 'NHS England Events', 'NHS England', 'https://www.events.england.nhs.uk/events', 'mixed', 'page_query', 'https://www.events.england.nhs.uk/events?page={n}', 5, FALSE, TRUE, 'Server-rendered Sigma ticketing portal. Listing /events?page=N (about 20 cards a page; walk until a page adds no new card). Card: data-url=/<id>, title, ''DD Month YYYY'', '' - location''. Detail /<id>: h1, .mvp_date, .mvp_address, .mvp_ticket blocks (label + FREE/price chip + Fully Booked badge), .mvp_body description. Titles are filtered by a clinical/education cue list minus an admin/comms/IT drop list; dropped titles are logged.'),
  (157, 'IMCAS', 'IMCAS', 'https://www.imcas.com/en/worldwide-events', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'Server-rendered. The site-wide Congresses menu (on /en/worldwide-events) lists IMCAS''s own congresses as ''IMCAS World 2027'' + ''28 - 30 January 2027, PARIS & ONLINE''; each links to /en/imcas-<name>-<year>. The agenda itself lists other organisers'' congresses (dropped, logged). INVEST investor day dropped. Congress page hero: weekday date range then ''Venue, City''; status block gives abstract open/closed. /registration is robots-disallowed so no fee tiers.'),
  (158, 'Orthopaedic Research Society (ORS)', 'ORS', 'https://www.ors.org/events/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, '/events/ is a Tockify JS widget (not used). Listing = the site menu items under Events (before Previous Meetings): each is a static event page; keep those that parse to an upcoming ''Month D - D, YYYY'' block with venue and City, State lines. Save-the-date annual meetings on /futureannualmeetings/ within 18 months become extra shells. Annual Meeting links Rates and Information (/register2027/) with a member/non-member x early/regular USD grid; a registration page is used only if its own heading names the event year (workshop link still points at the 2025 page).')
